/bin/zsh -c "python3 - <<'PY'
import glob, email, os
from email import policy
for f in sorted(glob.glob(os.path.expanduser('~/Library/Mail/V10/27F48433-8644-4505-BA3F-211815F6BFA5/*.mbox/*/Data/Messages/*emlx'))):
    raw=open(f,'rb').read()
    p=raw.find(b'\\n')
    try:
        msg=email.message_from_bytes(raw[p+1:], policy=policy.default)
        subj=msg.get('Subject','')
        body=''
        if msg.is_multipart():
            for part in msg.walk():
                if part.get_content_type()=='text/plain':
                    body=part.get_content(); break
            if not body:
                for part in msg.walk():
                    if part.get_content_type()=='text/html':
                        body=part.get_content(); break
        else:
            body=msg.get_content()
        body=' '.join(str(body).split())[:350]
        print(f'{os.path.basename(f)} | {subj} | {msg.get(\"From\",\"\")} | {body}')
    except Exception as e:
        print(os.path.basename(f), 'ERR', e)
PY"
